async function isUnsubscribed(userId, email) {
  if (!email) return false;
  try {
    const { rows } = await pool.query(
      `SELECT 1 FROM email_unsubscribes WHERE user_id=$1 AND LOWER(email)=LOWER($2) LIMIT 1`,
      [String(userId), email]
    );
    return rows.length > 0;
  } catch { return false; }
}

// Upserts an unsubscribe token record and returns the token (stable per user+email pair).
async function getOrCreateUnsubToken(userId, email, leadId) {
  const existing = await pool.query(
    `SELECT token FROM email_unsubscribes WHERE user_id=$1 AND LOWER(email)=LOWER($2) LIMIT 1`,
    [String(userId), email]
  );
  if (existing.rows.length) return existing.rows[0].token;
  const token = require('crypto').randomBytes(20).toString('hex');
  await pool.query(
    `INSERT INTO email_unsubscribes (user_id, email, token, lead_id) VALUES ($1,$2,$3,$4)
     ON CONFLICT (user_id, LOWER(email)) DO NOTHING`,
    [String(userId), email, token, leadId || null]
  );
  return token;
}

function buildUnsubFooter(unsubUrl, senderName) {
  const text = `\n\n--\n${senderName}\n\nTo unsubscribe from future emails, visit: ${unsubUrl}`;
  const html = `<br><br><hr style="border:none;border-top:1px solid #eee;margin:20px 0">
<p style="font-size:11px;color:#999;margin:0">${he(senderName)}</p>
<p style="font-size:10px;color:#bbb;margin:4px 0 0">
  <a href="${unsubUrl}" style="color:#bbb;text-decoration:underline">Unsubscribe</a> from future emails.
</p>`;
  return { text, html };
}

// ----------------------------------------------------------------------------
// Express
// ----------------------------------------------------------------------------
const app = express();

// Stripe webhooks need the raw body — must be before express.json()
app.use('/stripe/webhook', express.raw({ type: 'application/json' }));
app.use(express.json({ limit: '4mb' }));

// CORS — restrict to the known app origin; never wildcard.
const CORS_ORIGIN = process.env.APP_URL || `http://localhost:${PORT}`;
app.use((req, res, next) => {
  res.setHeader('Access-Control-Allow-Origin', CORS_ORIGIN);
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  if (req.method === 'OPTIONS') return res.sendStatus(204);
  next();
});

// Trust the Railway/PaaS proxy so express-rate-limit keys on the real client IP
// rather than the proxy's IP (otherwise every request shares a single bucket).
app.set('trust proxy', 1);

// Stricter brute-force guard on the auth surface. /auth/me is excluded — the
// SPA polls it on every mount/focus refetch and it's just a token introspection.
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => req.path === '/me',
});
app.use('/auth', authLimiter);

// HTML escaper for public-facing server-rendered pages — prevents XSS from user-submitted data.
function he(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

// Strip unsafe tags/attributes from AI-generated HTML (pricing_html, roi_section, etc.)
// Only called for content that is intentionally HTML (not escaped).
function sanitizeProposalHtml(html) {
  return String(html || '')
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<iframe[\s\S]*?<\/iframe>/gi, '')
    .replace(/\bon\w+\s*=/gi, 'data-removed=')
    .replace(/javascript\s*:/gi, '#');
}

// Generous global limiter. Inbound webhooks (Stripe/Vapi/Resend) and the
// public token-based pages a client can land on without a JWT are exempted —
// rate-limiting either would either let attackers DoS via webhook spam or
// break the client portal entirely.
const apiLimiter = rateLimit({
  windowMs: 60 * 1000,
  max: 300,
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => {
    const p = req.path;
    if (p.startsWith('/stripe/webhook')) return true;
    if (p.startsWith('/calls/webhook'))  return true;
    if (p.startsWith('/webhooks/'))      return true;
    if (p.startsWith('/track/'))         return true;
    if (p.startsWith('/portal/'))        return true;
    if (p.startsWith('/portfolio/'))     return true;
    if (p.startsWith('/quote-request/')) return true;
    if (p.startsWith('/hook/'))          return true;
    if (p.startsWith('/embed.js'))       return true;
    if (p.startsWith('/demo'))           return true;
    if (p.startsWith('/migrate/'))       return true;
    if (p.startsWith('/for/'))           return true;
    if (p.startsWith('/compare/'))       return true;
    if (p === '/calculator')             return true;
    if (p === '/stats.json')             return true;
    if (p === '/robots.txt' || p === '/sitemap.xml') return true;
    if (p === '/health' || p === '/test') return true;
    if (p.startsWith('/wrap-my-fleet')) return true;
    if (p.startsWith('/inbound-leads')) return false; // auth route, keep limited
    return false;
  },
});
app.use(apiLimiter);

// Rate limiter for the public /wrap-my-fleet consumer tool
const fleetToolLimiter = rateLimit({
  windowMs: 60 * 60 * 1000,  // 1 hour
  max: 5,
  standardHeaders: true, legacyHeaders: false,
  message: { error: 'Too many concept requests. Please try again in an hour.' },
});
const fleetSubmitLimiter = rateLimit({
  windowMs: 24 * 60 * 60 * 1000,  // 24 hours
  max: 10,
  standardHeaders: true, legacyHeaders: false,
  message: { error: 'Daily limit reached. Please try again tomorrow.' },
});

// Static serving is handled AFTER all API routes (see bottom of file)

// ----------------------------------------------------------------------------
// Auth middleware
// ----------------------------------------------------------------------------
// Web Push — lazily initialized so missing VAPID env vars don't crash boot
let webPush = null;
function getWebPush() {
  if (webPush) return webPush;
  const vapidPublic  = process.env.VAPID_PUBLIC_KEY;
  const vapidPrivate = process.env.VAPID_PRIVATE_KEY;
  const vapidMailto  = process.env.VAPID_MAILTO || 'mailto:admin@wrapos.app';
  if (!vapidPublic || !vapidPrivate) return null;
  try {
    webPush = require('web-push');
    webPush.setVapidDetails(vapidMailto, vapidPublic, vapidPrivate);
    return webPush;
  } catch (e) {
    console.warn('[web-push] Could not load module:', e.message);
    return null;
  }
}

async function sendPushToUser(userId, { title, body, url = '/', tag, requireInteraction = false }) {
  const wp = getWebPush();
  if (!wp) return;
  try {
    const { rows } = await pool.query('SELECT endpoint, p256dh, auth FROM push_subscriptions WHERE user_id=$1', [String(userId)]);
    if (!rows.length) return;
    const payload = JSON.stringify({ title, body, url, tag, requireInteraction });
    for (const sub of rows) {
      wp.sendNotification({ endpoint: sub.endpoint, keys: { p256dh: sub.p256dh, auth: sub.auth } }, payload)
        .catch(async (err) => {
          if (err.statusCode === 410 || err.statusCode === 404) {
            // Subscription expired — remove it
            await pool.query('DELETE FROM push_subscriptions WHERE endpoint=$1', [sub.endpoint]).catch(() => {});
          }
        });
    }
  } catch (e) {
    console.warn('[web-push] sendPushToUser error:', e.message);
  }
}

async function createNotification(userId, { type, title, body = '', metadata = {} }) {
  try {
    await pool.query(
      `INSERT INTO notifications (user_id, type, title, body, metadata) VALUES ($1,$2,$3,$4,$5)`,
      [String(userId), type, title, body, JSON.stringify(metadata)]
    );
    // Also fire web push for high-priority events (non-blocking)
    if (['new_lead', 'email_reply', 'design_approved', 'hot_prospect'].includes(type)) {
      sendPushToUser(userId, { title, body, url: '/', tag: type });
    }
  } catch (e) {
    console.warn('[notify]', e.message);
  }
}

function authMiddleware(req, res, next) {
  const header = req.headers.authorization || '';
  if (!header.startsWith('Bearer ')) return res.status(401).json({ error: 'No token' });
  try {
    req.user = jwt.verify(header.slice(7), JWT_SECRET);
    next();
  } catch {
    res.status(401).json({ error: 'Invalid or expired token' });
  }
}

// Tier hierarchy — higher rank includes all lower-tier features
const TIER_RANK = { wrapleads: 1, shopflow: 2, wrapos: 3 };

// Returns Express middleware that gates a route to users on minTier or higher.
// During trial, all features are unlocked (trial_tier = 'wrapos').
function requireTier(minTier) {
  return async (req, res, next) => {
    if (STRIPE_DISABLED) return next();
    try {
      const r = await pool.query(
        `SELECT sub_status, trial_ends_at, plan_tier FROM users WHERE id = $1`,
        [String(req.user.id)]
      );
      if (!r.rows.length) return res.status(401).json({ error: 'User not found' });
      const { sub_status, trial_ends_at, plan_tier } = r.rows[0];

      // Trial: active if trial_ends_at is in the future and status is still inactive
      const onTrial = sub_status === 'inactive' && trial_ends_at && new Date(trial_ends_at) > new Date();
      if (onTrial) {
        req.user.subStatus = 'trialing';
        req.user.planTier  = 'wrapos'; // trials get full access
        return next();
      }

      if (!['trialing', 'active', 'past_due'].includes(sub_status)) {
        return res.status(402).json({ error: 'Subscription required', sub_status });
      }

      // Trialing via Stripe (not the trial_ends_at path) also gets full access
      if (sub_status === 'trialing') {
        req.user.subStatus = 'trialing';
        req.user.planTier  = 'wrapos';
        return next();
      }

      // Check tier rank for paid subscribers
      const userRank     = TIER_RANK[plan_tier] || 1;
      const requiredRank = TIER_RANK[minTier]   || 1;
      if (userRank < requiredRank) {
        // 402 (not 403) so the frontend authFetch opens the PaywallModal
        return res.status(402).json({
          error:         'Plan upgrade required',
          required_tier: minTier,
          current_tier:  plan_tier || 'wrapleads',
          upgrade_price: TIER_PRICES[minTier],
        });
      }

      req.user.subStatus = sub_status;
      req.user.planTier  = plan_tier || 'wrapleads';
      next();
    } catch (e) {
      res.status(500).json({ error: e.message });
    }
  };
}

// Convenience aliases
const subMiddleware     = requireTier('wrapleads'); // backward-compat default
const requireShopFlow   = requireTier('shopflow');
const requireWrapOS     = requireTier('wrapos');

