// ── VIN Decoder (NHTSA free API) ──────────────────────────────────────────────
// Decodes a 17-character VIN into make/model/year/body class and maps it to our
// vehicle_type enum for use in quotes and job creation.
// No API key required — NHTSA data is public.
app.get('/tools/vin/:vin', async (req, res) => {
  const vin = (req.params.vin || '').trim().toUpperCase().replace(/[^A-HJ-NPR-Z0-9]/g, '');
  if (vin.length !== 17) return res.status(400).json({ error: 'VIN must be exactly 17 characters (A–Z, 0–9, no I/O/Q)' });

  try {
    const r = await fetch(`https://vpic.nhtsa.dot.gov/api/vehicles/decodevin/${vin}?format=json`, {
      signal: AbortSignal.timeout(8000),
    });
    if (!r.ok) return res.status(502).json({ error: `NHTSA API error: ${r.status}` });
    const data = await r.json();
    const results = data.Results || [];

    const find = (varName) => {
      const match = results.find((x) => x.Variable === varName);
      return match && match.Value && match.Value !== 'null' && match.Value !== 'Not Applicable'
        ? match.Value.trim() : null;
    };

    const make        = find('Make');
    const model       = find('Model');
    const year        = find('Model Year');
    const bodyClass   = find('Body Class');
    const gvwr        = find('Gross Vehicle Weight Rating From');
    const vehicleType = find('Vehicle Type');
    const series      = find('Series');
    const trim        = find('Trim');
    const doors       = find('Number of Doors');
    const fuel        = find('Fuel Type - Primary');
    const errorCode   = find('Error Code');

    if (errorCode && errorCode !== '0') {
      return res.status(422).json({ error: `NHTSA decode error: ${find('Error Text') || errorCode}` });
    }

    // Map to our vehicle_type enum
    const bc = (bodyClass || '').toLowerCase();
    const vt = (vehicleType || '').toLowerCase();
    let wrapType = 'other';
    if (/cargo van/i.test(bc) || /cargo van/i.test(model || '')) wrapType = 'cargo_van_standard';
    else if (/van/i.test(bc)) wrapType = 'cargo_van_standard';
    else if (/bus/i.test(vt) || /bus/i.test(bc)) wrapType = 'bus_school';
    else if (/tractor|semi/i.test(bc)) wrapType = 'semi_cab_only';
    else if (/pickup/i.test(bc)) wrapType = 'pickup_truck';
    else if (/sport utility/i.test(bc) || /\bsuv\b/i.test(bc)) wrapType = 'suv_large';
    else if (/sedan|coupe/i.test(bc)) wrapType = 'sedan';
    else if (/minivan|passenger van/i.test(bc)) wrapType = 'minivan';
    else if (/truck/i.test(bc)) wrapType = 'pickup_truck';
    else if (/crossover/i.test(bc)) wrapType = 'suv_large';

    const label = [year, make, model, series].filter(Boolean).join(' ');

    res.json({
      ok: true, vin,
      make, model, year, series, trim,
      bodyClass, gvwr, vehicleType, doors, fuel,
      wrapType, label,
    });
  } catch (e) {
    if (e.name === 'TimeoutError') return res.status(504).json({ error: 'NHTSA API timeout' });
    res.status(500).json({ error: e.message });
  }
});

// ── Computer Vision Vehicle Quoting ──────────────────────────────────────────

const VEHICLE_DIMENSIONS = {
  cargo_van_standard:  { label: 'Cargo Van (Standard)',    sqft: [200, 250] },
  cargo_van_high_roof: { label: 'Cargo Van (High Roof)',   sqft: [240, 290] },
  box_truck_16:        { label: '16ft Box Truck',          sqft: [310, 360] },
  box_truck_24:        { label: '24ft Box Truck',          sqft: [420, 480] },
  semi_cab_only:       { label: 'Semi Cab (no trailer)',   sqft: [200, 260] },
  semi_full:           { label: 'Semi + 53ft Trailer',     sqft: [620, 780] },
  pickup_truck:        { label: 'Full-Size Pickup',        sqft: [150, 200] },
  suv_large:           { label: 'Large SUV / Crossover',   sqft: [160, 210] },
  sedan:               { label: 'Sedan / Compact',         sqft: [100, 145] },
  minivan:             { label: 'Minivan / Passenger Van', sqft: [175, 220] },
  bus_school:          { label: 'School / Transit Bus',    sqft: [380, 550] },
  flatbed:             { label: 'Flatbed Truck',           sqft: [180, 250] },
  other:               { label: 'Vehicle',                 sqft: [150, 250] },
};

// Physical wrap dimensions (inches) per vehicle type and panel side.
// Used by /vision/ar-print-ready to produce correctly-sized HP Latex print files.
const PRINT_DIMS = {
  cargo_van_standard:  { label: 'Cargo Van (Standard)',    sides: { driver: { label: 'Driver Side', w: 168, h: 66 }, passenger: { label: 'Passenger Side', w: 168, h: 66 }, rear: { label: 'Rear Doors', w: 60, h: 60 } } },
  cargo_van_high_roof: { label: 'Cargo Van (High Roof)',   sides: { driver: { label: 'Driver Side', w: 168, h: 78 }, passenger: { label: 'Passenger Side', w: 168, h: 78 }, rear: { label: 'Rear Doors', w: 60, h: 74 } } },
  box_truck_16:        { label: '16ft Box Truck',          sides: { driver: { label: 'Driver Side', w: 194, h: 84 }, passenger: { label: 'Passenger Side', w: 194, h: 84 }, rear: { label: 'Rear Door', w: 96, h: 84 } } },
  box_truck_24:        { label: '24ft Box Truck',          sides: { driver: { label: 'Driver Side', w: 290, h: 96 }, passenger: { label: 'Passenger Side', w: 290, h: 96 }, rear: { label: 'Rear Door', w: 96, h: 96 } } },
  semi_cab_only:       { label: 'Semi Cab',                sides: { driver: { label: 'Driver Side', w: 120, h: 90 }, passenger: { label: 'Passenger Side', w: 120, h: 90 } } },
  semi_full:           { label: 'Semi + 53ft Trailer',     sides: { driver: { label: 'Trailer Driver Side', w: 636, h: 114 }, passenger: { label: 'Trailer Passenger Side', w: 636, h: 114 }, cab_driver: { label: 'Cab Driver Side', w: 120, h: 90 }, cab_passenger: { label: 'Cab Passenger Side', w: 120, h: 90 } } },
  pickup_truck:        { label: 'Full-Size Pickup',        sides: { driver: { label: 'Driver Side', w: 216, h: 66 }, passenger: { label: 'Passenger Side', w: 216, h: 66 }, tailgate: { label: 'Tailgate', w: 64, h: 24 } } },
  suv_large:           { label: 'Large SUV / Crossover',   sides: { driver: { label: 'Driver Side', w: 90, h: 60 }, passenger: { label: 'Passenger Side', w: 90, h: 60 }, hood: { label: 'Hood', w: 64, h: 48 } } },
  sedan:               { label: 'Sedan / Compact',         sides: { driver: { label: 'Driver Side', w: 70, h: 52 }, passenger: { label: 'Passenger Side', w: 70, h: 52 }, hood: { label: 'Hood', w: 58, h: 44 } } },
  minivan:             { label: 'Minivan / Passenger Van', sides: { driver: { label: 'Driver Side', w: 145, h: 62 }, passenger: { label: 'Passenger Side', w: 145, h: 62 }, rear: { label: 'Rear Hatch', w: 52, h: 48 } } },
  bus_school:          { label: 'School / Transit Bus',    sides: { driver: { label: 'Driver Side', w: 480, h: 84 }, passenger: { label: 'Passenger Side', w: 480, h: 84 }, rear: { label: 'Rear', w: 96, h: 84 } } },
  flatbed:             { label: 'Flatbed Truck',           sides: { driver: { label: 'Driver Side', w: 216, h: 48 }, passenger: { label: 'Passenger Side', w: 216, h: 48 } } },
  other:               { label: 'Vehicle (Generic)',       sides: { full: { label: 'Full', w: 168, h: 72 } } },
};

// ── HP Latex Print-Ready File Generator ──────────────────────────────────────
// Scales the AR concept to correct physical dimensions, adds registration marks
// and bleed, outputs a 150 DPI TIFF ready to drop into HP PrintOS or any RIP.
app.post('/vision/ar-print-ready', authMiddleware, async (req, res) => {
  const {
    imageUrl,
    vehicleKey = 'other',
    sideKey    = 'driver',
    printerWidthInches = 54,
    bleedInches        = 1.5,
  } = req.body || {};

  if (!imageUrl) return res.status(400).json({ error: 'imageUrl required' });

  const dim  = PRINT_DIMS[vehicleKey] || PRINT_DIMS.other;
  const side = dim.sides[sideKey] || Object.values(dim.sides)[0];
  const physW = side.w;  // actual wrap width in inches
  const physH = side.h;  // actual wrap height in inches
  const pw    = Math.max(12, Math.min(126, Number(printerWidthInches) || 54));
  const DPI   = 150;

  // Scale image to fill the printer width while preserving vehicle aspect ratio
  const scale   = pw / physW;
  const outW    = Math.round(pw   * DPI);
  const outH    = Math.round(physH * scale * DPI);
  const bleedPx = Math.round(bleedInches * scale * DPI);
  const canvasW = outW + 2 * bleedPx;
  const canvasH = outH + 2 * bleedPx;

  try {
    const sharp = require('sharp');

    // Decode image — supports data URLs (from gpt-image-1) and hosted URLs
    let imageBuffer;
    if (imageUrl.startsWith('data:')) {
      const comma = imageUrl.indexOf(',');
      if (comma === -1) throw new Error('Invalid data URL');
      imageBuffer = Buffer.from(imageUrl.slice(comma + 1), 'base64');
    } else {
      let parsedUrl;
      try { parsedUrl = new URL(imageUrl); } catch { throw new Error('Invalid image URL'); }
      if (parsedUrl.protocol !== 'https:') throw new Error('Only HTTPS image URLs are allowed');
      const r = await fetch(imageUrl);
      if (!r.ok) throw new Error('Could not fetch image URL');
      imageBuffer = Buffer.from(await r.arrayBuffer());
    }

    // Registration marks and trim line via SVG composite
    const gap = Math.max(4, Math.round(DPI * 0.125));   // 1/8" gap from trim edge
    const ml  = Math.max(8, Math.round(DPI * 0.25));    // 1/4" mark length
    const sw  = Math.max(1, Math.round(DPI / 100));     // stroke width
    const fs  = Math.max(9, Math.round(DPI * 0.075));   // label font size

    const tl = `${bleedPx}`;
    const tr = `${canvasW - bleedPx}`;
    const tt = `${bleedPx}`;
    const tb = `${canvasH - bleedPx}`;

    const svgMarks = [
      // Top-left
      `<line x1="${bleedPx - gap - ml}" y1="${tl}" x2="${bleedPx - gap}" y2="${tl}"/>`,
      `<line x1="${tl}" y1="${bleedPx - gap - ml}" x2="${tl}" y2="${bleedPx - gap}"/>`,
      // Top-right
      `<line x1="${canvasW - bleedPx + gap}" y1="${tt}" x2="${canvasW - bleedPx + gap + ml}" y2="${tt}"/>`,
      `<line x1="${tr}" y1="${bleedPx - gap - ml}" x2="${tr}" y2="${bleedPx - gap}"/>`,
      // Bottom-left
      `<line x1="${bleedPx - gap - ml}" y1="${tb}" x2="${bleedPx - gap}" y2="${tb}"/>`,
      `<line x1="${tl}" y1="${canvasH - bleedPx + gap}" x2="${tl}" y2="${canvasH - bleedPx + gap + ml}"/>`,
      // Bottom-right
      `<line x1="${canvasW - bleedPx + gap}" y1="${tb}" x2="${canvasW - bleedPx + gap + ml}" y2="${tb}"/>`,
      `<line x1="${tr}" y1="${canvasH - bleedPx + gap}" x2="${tr}" y2="${canvasH - bleedPx + gap + ml}"/>`,
    ].join('');

    const labelY = canvasH - Math.max(3, bleedPx - 4);
    const svgOverlay = `<svg width="${canvasW}" height="${canvasH}" xmlns="http://www.w3.org/2000/svg">
<g stroke="black" stroke-width="${sw}" fill="none">${svgMarks}</g>
<rect x="${bleedPx}" y="${bleedPx}" width="${outW}" height="${outH}" fill="none" stroke="red" stroke-width="${sw}" stroke-dasharray="${ml / 2} ${gap}"/>
<text x="${canvasW / 2}" y="${labelY}" text-anchor="middle" font-family="sans-serif" font-size="${fs}px" fill="#444">
  ${dim.label} · ${side.label} · ${physW}"×${physH}" printed at ${pw}" wide · ${bleedInches}" bleed · ${DPI} DPI · HP Latex ready
</text>
</svg>`;

    const tiffBuf = await sharp(imageBuffer)
      .resize(outW, outH, { fit: 'fill', kernel: 'lanczos3' })
      .extend({ top: bleedPx, bottom: bleedPx, left: bleedPx, right: bleedPx, background: { r: 255, g: 255, b: 255, alpha: 1 } })
      .composite([{ input: Buffer.from(svgOverlay), top: 0, left: 0 }])
      .tiff({ xres: DPI / 25.4, yres: DPI / 25.4, compression: 'lzw' })
      .toBuffer();

    const filename = `wrap-${vehicleKey}-${sideKey}-${pw}in.tif`;
    res.setHeader('Content-Type', 'image/tiff');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    res.setHeader('Content-Length', tiffBuf.length);
    res.setHeader('X-Print-Width-In',  String(pw));
    res.setHeader('X-Print-Height-In', String(Math.round(physH * scale * 10) / 10));
    res.send(tiffBuf);
  } catch (e) {
    console.error('[ar-print-ready]', e.message);
    res.status(500).json({ error: e.message });
  }
});

app.post('/vision/quote-vehicle', authMiddleware, upload.single('image'), async (req, res) => {
  if (!req.file) return res.status(400).json({ error: 'No image uploaded' });
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return res.status(503).json({ error: 'AI not configured' });

  try {
    const base64 = req.file.buffer.toString('base64');
    const mimeType = req.file.mimetype || 'image/jpeg';

    const resp = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 300,
        messages: [{
          role: 'user',
          content: [
            { type: 'image', source: { type: 'base64', media_type: mimeType, data: base64 } },
            { type: 'text', text: `Identify the vehicle in this image. Return ONLY valid JSON:\n{"vehicleKey":"<key>","confidence":"high|medium|low","notes":"<brief description>"}\nValid keys: ${Object.keys(VEHICLE_DIMENSIONS).join(', ')}. Pick the closest match.` },
          ],
        }],
      }),
    });
    const data = await resp.json();
    const text = data.content?.[0]?.text || '{}';
    const match = text.match(/\{[\s\S]*\}/);
    const parsed = JSON.parse(match ? match[0] : '{}');

    const key = parsed.vehicleKey && VEHICLE_DIMENSIONS[parsed.vehicleKey] ? parsed.vehicleKey : 'other';
    const dim = VEHICLE_DIMENSIONS[key];

    // Compute quote ranges
    const settingsRow = await pool.query(`SELECT settings_json FROM users WHERE id=$1`, [String(req.user.id)]);
    const s = settingsRow.rows[0]?.settings_json || {};
    const priceLow  = parseFloat(s.pricePerSqftLow  || '8');
    const priceHigh = parseFloat(s.pricePerSqftHigh || '14');

    const quotes = {
      full:    { label: 'Full Wrap',    low: Math.round(dim.sqft[0] * 1.0 * priceLow),  high: Math.round(dim.sqft[1] * 1.0 * priceHigh) },
      partial: { label: 'Partial Wrap', low: Math.round(dim.sqft[0] * 0.5 * priceLow),  high: Math.round(dim.sqft[1] * 0.5 * priceHigh) },
      spot:    { label: 'Spot / Logo',  low: Math.round(dim.sqft[0] * 0.2 * priceLow),  high: Math.round(dim.sqft[1] * 0.2 * priceHigh) },
    };

    res.json({ ok: true, vehicleKey: key, vehicleLabel: dim.label, confidence: parsed.confidence || 'medium', notes: parsed.notes || '', sqftRange: dim.sqft, quotes });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// ── AI Design Generation ──────────────────────────────────────────────────────

app.post('/ai/design-brief', authMiddleware, requireWrapOS, async (req, res) => {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return res.status(503).json({ error: 'AI not configured' });
  const { vehicleType, primaryColor, secondaryColor, style, description, companyName } = req.body;

  const prompt = `You are a professional vehicle wrap designer. Create a detailed design brief for this wrap project.

Vehicle: ${vehicleType || 'cargo van'}
Company: ${companyName || 'the client'}
Primary color: ${primaryColor || 'blue'}
Secondary color: ${secondaryColor || 'white'}
Style: ${style || 'bold and modern'}
Client description: ${description || 'professional fleet wrap'}

Return ONLY valid JSON:
{
  "primary_color": "<hex>",
  "secondary_color": "<hex>",
  "style": "<style description>",
  "layout": "<detailed layout description for the wrap panels>",
  "typography": "<font/text recommendation>",
  "dall_e_prompt": "<detailed DALL-E 3 prompt for generating a photorealistic concept render of this wrapped vehicle>"
}

The dall_e_prompt must specify: exact vehicle type, wrap design, colors, finish (matte/gloss), studio photography style, white background.`;

  try {
    const text = await claudeHaiku(apiKey, [{ role: 'user', content: prompt }], 800);
    const match = text.match(/\{[\s\S]*\}/);
    const brief = JSON.parse(match ? match[0] : '{}');
    res.json({ ok: true, brief });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.post('/ai/generate-mockup', authMiddleware, requireWrapOS, async (req, res) => {
  const { brief } = req.body;
  if (!brief?.dall_e_prompt) return res.status(400).json({ error: 'No design brief provided' });

  const settingsRow = await pool.query(`SELECT settings_json FROM users WHERE id=$1`, [String(req.user.id)]);
  const s = settingsRow.rows[0]?.settings_json || {};
  const openaiKey = s.openaiApiKey;
  if (!openaiKey) return res.status(503).json({ error: 'OpenAI API key not configured in Settings' });

  try {
    const resp = await fetch('https://api.openai.com/v1/images/generations', {
      method: 'POST',
      headers: { Authorization: `Bearer ${openaiKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: 'dall-e-3',
        prompt: brief.dall_e_prompt,
        n: 1,
        size: '1792x1024',
        quality: 'standard',
        response_format: 'url',
      }),
    });
    const data = await resp.json();
    if (!resp.ok) throw new Error(data.error?.message || 'DALL-E error');
    const image_url = data.data?.[0]?.url;
    res.json({ ok: true, image_url, brief });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// ── AR / Wrap Mockup Preview ──────────────────────────────────────────────────

app.post('/vision/ar-preview', authMiddleware, upload.single('image'), async (req, res) => {
  if (!req.file) return res.status(400).json({ error: 'No image uploaded' });

  const settingsRow = await pool.query(`SELECT settings_json FROM users WHERE id=$1`, [String(req.user.id)]);
  const s = settingsRow.rows[0]?.settings_json || {};
  const openaiKey = s.openaiApiKey;
  if (!openaiKey) return res.status(503).json({ error: 'OpenAI API key required for AR preview — add it in Settings' });

  const wrapDescription = req.body.wrapDescription || 'professional vehicle wrap with bold graphics';
  const brandColors = (req.body.brandColors || '').trim();
  const competitive = req.body.competitive === '1' || req.body.competitive === 'true';
  const variants = Math.max(1, Math.min(3, parseInt(req.body.variants, 10) || 1));

  try {
    // Store original as base64 data URL for side-by-side display
    const originalDataUrl = `data:${req.file.mimetype};base64,${req.file.buffer.toString('base64')}`;

    // Build the wrap prompt, layering in brand colors + competitive framing when requested
    let prompt = `Apply a professional vehicle wrap to this exact vehicle. Wrap design: ${wrapDescription}.`;
    if (brandColors) prompt += ` Incorporate these exact brand colors prominently throughout the design: ${brandColors}.`;
    if (competitive) prompt += ` Make the branding bold, large, and high-contrast for maximum visibility and on-road impact.`;
    prompt += ` Keep the vehicle shape, perspective, lighting, and surroundings identical. Make the wrap look photorealistic and production-quality.`;

    // Use gpt-image-1 edit endpoint with the uploaded photo.
    // Attempt batch generation (n > 1) first; if the API rejects the n parameter
    // (some endpoint versions don't support it) fall back to sequential single calls.
    const FormDataNode = (await import('form-data')).default;

    async function singleEdit() {
      const f = new FormDataNode();
      f.append('model', 'gpt-image-1');
      f.append('image', req.file.buffer, { filename: 'vehicle.jpg', contentType: req.file.mimetype });
      f.append('prompt', prompt);
      f.append('size', '1536x1024');
      const r = await fetch('https://api.openai.com/v1/images/edits', {
        method: 'POST',
        headers: { Authorization: `Bearer ${openaiKey}`, ...f.getHeaders() },
        body: f,
      });
      const d = await r.json();
      if (!r.ok) throw new Error(d.error?.message || 'OpenAI image edit error');
      const toUrl = (item) => item.url || (item.b64_json ? `data:image/png;base64,${item.b64_json}` : null);
      return (d.data || []).map(toUrl).filter(Boolean);
    }

    let image_urls = [];

    if (variants > 1) {
      // Try batch first
      try {
        const form = new FormDataNode();
        form.append('model', 'gpt-image-1');
        form.append('image', req.file.buffer, { filename: 'vehicle.jpg', contentType: req.file.mimetype });
        form.append('prompt', prompt);
        form.append('size', '1536x1024');
        form.append('n', String(variants));
        const resp = await fetch('https://api.openai.com/v1/images/edits', {
          method: 'POST',
          headers: { Authorization: `Bearer ${openaiKey}`, ...form.getHeaders() },
          body: form,
        });
        const data = await resp.json();
        if (resp.ok && data.data?.length > 1) {
          const toUrl = (item) => item.url || (item.b64_json ? `data:image/png;base64,${item.b64_json}` : null);
          image_urls = (data.data || []).map(toUrl).filter(Boolean);
        } else {
          // API accepted request but returned only one, or rejected n — fall back
          throw new Error('batch-unsupported');
        }
      } catch {
        // Sequential fallback: fire variants calls in parallel (respects rate limits better than series)
        const calls = Array.from({ length: variants }, () => singleEdit());
        const settled = await Promise.allSettled(calls);
        image_urls = settled
          .filter((r) => r.status === 'fulfilled')
          .flatMap((r) => (r.status === 'fulfilled' ? r.value : []));
        if (!image_urls.length) throw new Error('All variant generations failed');
      }
    } else {
      image_urls = await singleEdit();
    }

    res.json({ ok: true, image_url: image_urls[0], image_urls, original_url: originalDataUrl });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// ── Pitch Mode — in-person sales demo (brand lookup + camera → live wrap) ─────
//
// Two endpoints power the field-sales pitch tool:
//   POST /vision/brand-lookup     companyName → { domain, logo_url, primary/secondary colors, tagline }
//   POST /vision/pitch-preview    image + brand info → photorealistic wrap mockup in the lead's colors
//
// Logo URL is derived from Clearbit (https://logo.clearbit.com/{domain}). It's
// free, requires no key, and 404s gracefully if the domain has no logo — the
// frontend just falls back to initials. Brand colors come from Claude.

app.post('/vision/brand-lookup', authMiddleware, async (req, res) => {
  const companyName = String(req.body?.companyName || '').trim();
  if (!companyName) return res.status(400).json({ error: 'Missing companyName' });

  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return res.status(503).json({ error: 'AI not configured (ANTHROPIC_API_KEY)' });

  try {
    const text = await claudeHaiku(apiKey, [{
      role: 'user',
      content: `You are a brand-identity researcher. For the company below, return JSON only — no prose, no code fences — with your best guess for these exact fields. If you genuinely don't know a value, use an empty string for strings (never null).

Company: "${companyName}"

Required JSON shape:
{
  "name": "official display name, e.g. 'FedEx' not 'fedex inc'",
  "domain": "primary website domain, e.g. 'fedex.com' (no protocol, no www)",
  "primary_color": "main brand color as #rrggbb hex, e.g. '#4D148C'",
  "secondary_color": "secondary/accent brand color as #rrggbb hex",
  "tagline": "short positioning line if widely known, otherwise empty string"
}

For well-known brands use their actual colors. For unknown companies, pick a plausible, professional color pair based on the industry hint in the name. Always return valid hex colors.`,
    }], 400);

    const cleaned = text.replace(/```json|```/g, '').trim();
    let brand;
    try { brand = JSON.parse(cleaned); }
    catch { return res.status(502).json({ error: 'Brand lookup returned malformed JSON' }); }

    // Normalize: keep only the fields we promised, force hex shape.
    const hex = (v) => {
      const s = String(v || '').trim();
      return /^#[0-9a-f]{6}$/i.test(s) ? s.toUpperCase() : '';
    };
    const domain = String(brand.domain || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '');
    const result = {
      name: String(brand.name || companyName).trim(),
      domain,
      logo_url: domain ? `https://logo.clearbit.com/${domain}` : '',
      primary_color: hex(brand.primary_color) || '#1F2937',
      secondary_color: hex(brand.secondary_color) || '#F3F4F6',
      tagline: String(brand.tagline || '').trim(),
    };
    res.json({ ok: true, brand: result });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.post('/vision/pitch-preview', authMiddleware, upload.single('image'), async (req, res) => {
  if (!req.file) return res.status(400).json({ error: 'No image uploaded' });

  const settingsRow = await pool.query(`SELECT settings_json FROM users WHERE id=$1`, [req.user.id]);
  const s = settingsRow.rows[0]?.settings_json || {};
  const openaiKey = s.openaiApiKey;
  if (!openaiKey) return res.status(503).json({ error: 'OpenAI API key required — add it in Settings → Design Studio' });

  const companyName    = String(req.body.companyName || '').trim();
  const primaryColor   = String(req.body.primary_color || '#1F2937').trim();
  const secondaryColor = String(req.body.secondary_color || '#F3F4F6').trim();
  const tagline        = String(req.body.tagline || '').trim();

  const STYLE_LIBRARY = {
    full_wrap:   { label: 'Full Wrap',     clause: 'full color-change wrap covering the entire body in the brand color' },
    partial:     { label: 'Partial Wrap',  clause: 'partial wrap with bold panels on the doors, hood, and rear quarter' },
    stripes:     { label: 'Stripes',       clause: 'racing-inspired stripe wrap running front to back' },
    logo_focus:  { label: 'Logo + Contact', clause: 'clean white-or-black base with the brand logo and contact band prominently on the doors and rear' },
    matte_brand: { label: 'Matte Premium', clause: 'matte-finish color-change wrap in the brand color, premium luxury look' },
  };

  // Accept either `styles` (CSV) for multi-variant or a single `style` for back-compat.
  const stylesRaw = String(req.body.styles || req.body.style || 'full_wrap');
  const requested = stylesRaw.split(',').map(s => s.trim()).filter(Boolean);
  const styles = requested.filter(s => STYLE_LIBRARY[s]);
  const stylesToRun = styles.length ? styles.slice(0, 4) : ['full_wrap'];

  function buildPrompt(styleKey) {
    const { clause } = STYLE_LIBRARY[styleKey] || STYLE_LIBRARY.full_wrap;
    return [
      `Apply a professional vehicle wrap to this exact vehicle for the brand "${companyName}".`,
      `Use the brand's actual colors: ${primaryColor} as the dominant base color and ${secondaryColor} as the accent.`,
      `Style: ${clause}.`,
      `Place a clean rendering of the "${companyName}" wordmark on the doors and rear panel.`,
      tagline ? `Include the tagline "${tagline}" in small type below the wordmark.` : '',
      `Keep the vehicle shape, perspective, lighting, and surroundings identical.`,
      `Photorealistic, production-quality, as if installed by a top-tier wrap shop.`,
    ].filter(Boolean).join(' ');
  }

  try {
    const originalDataUrl = `data:${req.file.mimetype};base64,${req.file.buffer.toString('base64')}`;
    const FormDataNode = (await import('form-data')).default;

    async function runOne(styleKey) {
      const form = new FormDataNode();
      form.append('model', 'gpt-image-1');
      form.append('image', req.file.buffer, { filename: 'vehicle.jpg', contentType: req.file.mimetype });
      form.append('prompt', buildPrompt(styleKey));
      form.append('size', '1536x1024');
      const resp = await fetch('https://api.openai.com/v1/images/edits', {
        method: 'POST',
        headers: { Authorization: `Bearer ${openaiKey}`, ...form.getHeaders() },
        body: form,
      });
      const data = await resp.json();
      if (!resp.ok) throw new Error(data.error?.message || 'OpenAI image edit error');
      const image_url = data.data?.[0]?.url || (`data:image/png;base64,${data.data?.[0]?.b64_json}`);
      return { style: styleKey, label: STYLE_LIBRARY[styleKey].label, image_url };
    }

    const settled = await Promise.allSettled(stylesToRun.map(runOne));
    const variants = settled.filter(r => r.status === 'fulfilled').map(r => r.value);
    if (!variants.length) {
      const reason = settled[0]?.status === 'rejected' ? settled[0].reason?.message : 'No variants generated';
      throw new Error(reason || 'No variants generated');
    }

    res.json({
      ok: true,
      variants,
      original_url: originalDataUrl,
      // back-compat for old clients
      image_url: variants[0].image_url,
    });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

