// ── AI Lead Intelligence Brief ────────────────────────────────────────────────
// POST /ai/lead-brief
// Generates a compact deal-prep dossier for any lead: company overview,
// fit rationale, pitch angle, icebreaker, 3 likely objections, next action.
// Uses lead data + activity history + loss history for similar companies.
app.post('/ai/lead-brief', authMiddleware, async (req, res) => {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return res.status(503).json({ error: 'Anthropic API key not configured' });

  const { leadId } = req.body;
  if (!leadId) return res.status(400).json({ error: 'leadId required' });

  const uid = String(req.user.id);
  try {
    const [leadR, settingsR, activitiesR, similarWinsR] = await Promise.all([
      pool.query(
        `SELECT l.*, l.notes AS lead_notes
           FROM leads l WHERE l.id=$1 AND l.user_id=$2`,
        [leadId, uid]
      ),
      pool.query(`SELECT settings_json FROM users WHERE id=$1`, [uid]),
      pool.query(
        `SELECT type, subject, body, metadata, created_at
           FROM lead_activities WHERE lead_id=$1 AND user_id=$2
           ORDER BY created_at DESC LIMIT 8`,
        [leadId, uid]
      ),
      pool.query(
        `SELECT company, category, status, fleet_size, notes
           FROM leads WHERE user_id=$1 AND status='won' AND category=(
             SELECT category FROM leads WHERE id=$2 AND user_id=$1 LIMIT 1
           ) LIMIT 3`,
        [uid, leadId]
      ),
    ]);

    const lead = leadR.rows[0];
    if (!lead) return res.status(404).json({ error: 'Lead not found' });

    const s = settingsR.rows[0]?.settings_json || {};
    const shopName = s.companyName || 'our shop';
    const activities = activitiesR.rows;
    const similarWins = similarWinsR.rows;

    const actSummary = activities.length
      ? activities.map(a => `${a.type}: ${a.subject || a.body || ''}`).join('; ')
      : 'No activity yet';

    const prompt = `You are a strategic sales advisor helping ${shopName}, a vehicle wrap shop. Write a compact deal-prep brief for the following prospect.

LEAD DATA:
- Company: ${lead.company}
- Category: ${lead.category}
- Fleet size: ${lead.fleet_size || 'unknown'}
- Location: ${lead.city || ''}, ${lead.state || ''}
- Contact: ${lead.contact_name || 'unknown'} (${lead.contact_title || 'unknown role'})
- Website: ${lead.website || 'none'}
- Current stage: ${lead.status}
- Notes: ${lead.lead_notes || 'none'}
- Pitch angle on file: ${lead.pitch_angle || 'none'}
- Recent activity: ${actSummary}
${similarWins.length ? `- Similar won deals in this category: ${similarWins.map(w => w.company).join(', ')}` : ''}

Write a structured brief with EXACTLY these 5 sections (use the exact headers):
**COMPANY FIT** — 2 sentences: who they are and why they're a strong wrap prospect right now.
**PITCH ANGLE** — 1-2 sentences: the most compelling angle for this specific company.
**ICEBREAKER** — 1 concrete opening line for an email or call (reference something specific about them).
**OBJECTIONS** — 3 bullet points: the most likely objections and a 1-sentence counter for each.
**NEXT ACTION** — 1 specific, actionable step for today.

Keep each section tight. No fluff. Sound like a street-smart sales pro, not a consultant.`;

    const text = await claudeHaiku(apiKey, [{ role: 'user', content: prompt }], 600);
    res.json({ ok: true, brief: text.trim() });
  } catch (e) {
    console.error('[ai/lead-brief]', e.message);
    res.status(500).json({ error: 'Failed to generate brief' });
  }
});

// ── AI Call Script Generator ──────────────────────────────────────────────────
// POST /ai/call-script  (requireShopFlow)
// Generates a structured phone sales script customized to the lead's profile.
app.post('/ai/call-script', authMiddleware, requireShopFlow, async (req, res) => {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return res.status(503).json({ error: 'Anthropic API key not configured' });

  const { leadId } = req.body;
  if (!leadId) return res.status(400).json({ error: 'leadId required' });

  const uid = String(req.user.id);
  try {
    const [leadR, settingsR] = await Promise.all([
      pool.query('SELECT * FROM leads WHERE id=$1 AND user_id=$2', [leadId, uid]),
      pool.query('SELECT settings_json FROM users WHERE id=$1', [uid]),
    ]);
    const lead = leadR.rows[0];
    if (!lead) return res.status(404).json({ error: 'Lead not found' });

    const settings = settingsR.rows[0]?.settings_json || {};
    const shopName = settings.companyName || 'our shop';
    const shopServices = settings.companyServices || 'vehicle wraps and fleet graphics';

    const CAT_CONTEXT = {
      fleet: 'commercial fleet wrap — focus on brand visibility, driver acquisition, ROI vs. traditional advertising',
      dinoc: 'DI-NOC architectural film — surface renovation without demolition, commercial interiors, healthcare, hospitality',
      gc_referral: 'commercial graphics spec through a general contractor relationship — position as the trusted sub for branded environments',
      construction: 'construction fleet and equipment wrap — brand on the jobsite, referral generation, professional image',
      colorchange: 'vehicle color-change wrap — premium aesthetics, paint protection, reversibility vs. respray',
      racing: 'race car / motorsport livery — sponsor visibility, team identity, technical vinyl expertise',
      reatec: 'Rea Tec film — ultra-realistic stone, marble, wood surface renovation without demo',
      wallgraphics: 'wall and window graphics — retail environments, office branding, wayfinding',
      design: 'custom design and branding — visual identity, artwork, brand consistency across media',
    };

    const context = CAT_CONTEXT[lead.category] || 'vehicle graphics and wrap services';
    const fleetNote = lead.fleet_size ? `They operate a fleet of approximately ${lead.fleet_size} vehicles.` : '';
    const locationNote = lead.city && lead.state ? `They're based in ${lead.city}, ${lead.state}.` : '';
    const pitchNote = lead.pitch_angle ? `Previous pitch angle noted: ${lead.pitch_angle}.` : '';
    const statusNote = lead.status !== 'new' ? `Lead is currently in "${lead.status}" stage.` : '';

    const prompt = `You are a top-performing sales coach for ${shopName}, a vehicle wrap and graphics shop specializing in ${shopServices}.

Generate a concise, natural-sounding phone call script for reaching out to ${lead.company || 'this prospect'}.

Lead context:
- Category: ${context}
- ${fleetNote}
- ${locationNote}
- ${pitchNote}
- ${statusNote}

Return a JSON object with exactly these fields:
{
  "opening": "A 2-3 sentence warm opening that mentions the company by name, establishes credibility, and earns 30 more seconds",
  "pitch": "3-4 sentences: the core value proposition specific to this category and prospect. Be concrete — mention impressions, ROI, or transformation.",
  "objections": [
    { "q": "objection 1", "a": "response 1" },
    { "q": "objection 2", "a": "response 2" },
    { "q": "objection 3", "a": "response 3" }
  ],
  "close": "A specific, low-pressure call to action — suggest a 15-minute site visit or sending over a concept design"
}

Be direct and confident. No filler phrases like "Great question!" or "Absolutely!" Write how a real wrap shop owner talks — not corporate sales speak.`;

    const Anthropic = require('@anthropic-ai/sdk');
    const client = new Anthropic.default({ apiKey });
    const msg = await client.messages.create({
      model: 'claude-opus-4-5',
      max_tokens: 800,
      messages: [{ role: 'user', content: prompt }],
    });
    const raw = msg.content[0].text.trim();
    const jsonMatch = raw.match(/\{[\s\S]*\}/);
    if (!jsonMatch) throw new Error('AI response was not valid JSON');
    const script = JSON.parse(jsonMatch[0]);
    res.json({ ok: true, script });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// ── Follow-up Recommendation ──────────────────────────────────────────────────
// Returns top contact time slots derived from this user's historical activity
// (days/hours when leads moved to replied/meeting/proposal/won).
app.get('/leads/:id/followup-recommendation', authMiddleware, async (req, res) => {
  const uid = String(req.user.id);
  const leadId = parseInt(req.params.id, 10);
  if (isNaN(leadId)) return res.status(400).json({ error: 'Invalid lead id' });

  try {
    // Verify lead belongs to this user
    const leadR = await pool.query(
      `SELECT id, category, status, company FROM leads WHERE id=$1 AND user_id=$2`,
      [leadId, uid]
    );
    if (!leadR.rows.length) return res.status(404).json({ error: 'Lead not found' });
    const lead = leadR.rows[0];

    // Find the user's successful contact events (status advances) by hour/dow
    const histR = await pool.query(
      `SELECT
         EXTRACT(DOW FROM created_at AT TIME ZONE 'UTC')::INT  AS dow,
         EXTRACT(HOUR FROM created_at AT TIME ZONE 'UTC')::INT AS hour,
         COUNT(*)::INT AS hits
       FROM lead_activities
       WHERE user_id = $1
         AND type IN ('status_change','email_sent','call_completed','reply_received')
         AND notes ILIKE ANY(ARRAY['%replied%','%meeting%','%proposal%','%won%','%positive%','%interested%'])
       GROUP BY dow, hour
       ORDER BY hits DESC
       LIMIT 50`,
      [uid]
    );

    const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

    // Aggregate by (dow, hour) bucket and pick top 3
    const buckets = histR.rows;
    const top3 = buckets.slice(0, 3).map((b) => {
      const h = b.hour;
      const ampm = h >= 12 ? 'PM' : 'AM';
      const h12 = h === 0 ? 12 : h > 12 ? h - 12 : h;
      return {
        dow: b.dow,
        hour: b.hour,
        hits: b.hits,
        label: `${DAYS[b.dow]}s around ${h12}:00 ${ampm}`,
      };
    });

    // Fallback when no history yet: weekday business hours
    const fallback = [
      { dow: 2, hour: 10, hits: 0, label: 'Tuesdays around 10:00 AM' },
      { dow: 3, hour: 14, hits: 0, label: 'Wednesdays around 2:00 PM' },
      { dow: 4, hour: 9,  hits: 0, label: 'Thursdays around 9:00 AM'  },
    ];
    const slots = top3.length > 0 ? top3 : fallback;
    const dataSource = top3.length > 0 ? 'historical' : 'default';

    // Build summary sentence
    let summary;
    if (dataSource === 'historical') {
      summary = `Based on your past activity, ${lead.company} (${lead.category}) is most reachable on ${slots[0].label}.`;
    } else {
      summary = `No response history yet. These are high-performing windows for ${lead.category} leads industry-wide.`;
    }

    res.json({ ok: true, slots, summary, dataSource, lead: { id: lead.id, company: lead.company } });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// ── Onboarding Status ─────────────────────────────────────────────────────────
// Returns completion status for the 5-step setup checklist.
app.get('/onboarding/status', authMiddleware, async (req, res) => {
  const uid = String(req.user.id);
  try {
    const [emailR, aiEmailR, seqR, callR, bidR] = await Promise.all([
      // Step 1: sent a tracked email
      pool.query(`SELECT 1 FROM email_tracking WHERE user_id=$1 LIMIT 1`, [uid]),
      // Step 2: generated an AI email
      pool.query(`SELECT 1 FROM lead_activities WHERE user_id=$1 AND type IN ('email_generated','email_copied') LIMIT 1`, [uid]),
      // Step 3: activated a drip sequence
      pool.query(`SELECT 1 FROM email_queue WHERE user_id=$1 LIMIT 1`, [uid]),
      // Step 4: logged a call or booked a meeting
      pool.query(`SELECT 1 FROM lead_activities WHERE user_id=$1 AND type IN ('called','meeting_set') LIMIT 1`, [uid]),
      // Step 5: created a bid
      pool.query(`SELECT 1 FROM bids WHERE user_id=$1 LIMIT 1`, [uid]),
    ]);

    const steps = [
      { id: 'email_sent',    done: emailR.rows.length > 0,   title: 'Send your first email',       hint: 'Open a lead → Email tab → Generate & Send' },
      { id: 'ai_email',     done: aiEmailR.rows.length > 0,  title: 'Generate an AI email',         hint: 'Open a lead → Email tab → Generate Email' },
      { id: 'sequence',     done: seqR.rows.length > 0,      title: 'Activate a drip sequence',    hint: 'Open a lead → Email tab → Activate Sequence' },
      { id: 'call_meeting', done: callR.rows.length > 0,     title: 'Log a call or meeting',       hint: 'Open a lead → Activity tab → Log Call / Meeting Set' },
      { id: 'bid',          done: bidR.rows.length > 0,      title: 'Track your first bid',        hint: 'Switch to Bids view → Add New Bid' },
    ];

    const completed = steps.filter((s) => s.done).length;
    res.json({ ok: true, steps, completed, total: steps.length });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// GET /leads/:id/similar-wins — find the user's won deals most similar to this lead
// Used for social proof: "We wrapped 35 trucks for a similar fleet in Ohio last year."
app.get('/leads/:id/similar-wins', authMiddleware, async (req, res) => {
  const uid = String(req.user.id);
  const leadId = parseInt(req.params.id, 10);
  if (isNaN(leadId)) return res.status(400).json({ error: 'Invalid id' });
  try {
    const { rows: [lead] } = await pool.query(
      `SELECT category, state, city, fleet_size FROM leads WHERE id=$1 AND user_id=$2`,
      [leadId, uid]
    );
    if (!lead) return res.status(404).json({ error: 'Lead not found' });

    // Find won leads sorted by relevance: same category + same state first, then same category
    const { rows: wins } = await pool.query(`
      SELECT id, company, category, state, city, fleet_size,
        CASE
          WHEN category = $2 AND state = $3 THEN 3
          WHEN category = $2                THEN 2
          WHEN state = $3                   THEN 1
          ELSE 0
        END AS relevance_score,
        updated_at AS won_at
      FROM leads
      WHERE user_id = $1
        AND status = 'won'
        AND id != $4
      ORDER BY relevance_score DESC, updated_at DESC
      LIMIT 5
    `, [uid, lead.category, lead.state, leadId]);

    // Also find relevant installed jobs (completed installs — even stronger proof)
    const { rows: jobs } = await pool.query(`
      SELECT j.id, j.company, j.vehicle_count, j.vehicle_type, j.wrap_category, j.install_date,
             l.state, l.city
      FROM installed_jobs j
      LEFT JOIN leads l ON l.id = j.lead_id
      WHERE j.user_id = $1
        AND (j.wrap_category = $2 OR l.state = $3)
      ORDER BY j.install_date DESC
      LIMIT 3
    `, [uid, lead.category, lead.state]);

    res.json({ wins, jobs, leadCategory: lead.category, leadState: lead.state });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── AI Notes Summary ──────────────────────────────────────────────────────────
// Condenses a lead's journal entries + pinned notes into an executive brief.
app.post('/leads/:id/notes-summary', authMiddleware, async (req, res) => {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return res.status(503).json({ error: 'AI not configured' });

  const id = parseInt(req.params.id);
  if (!id) return res.status(400).json({ error: 'Invalid id' });
  const uid = String(req.user.id);

  try {
    // Ownership check + lead data
    const leadR = await pool.query(
      `SELECT company, category, status, notes FROM leads WHERE id=$1 AND user_id=$2`,
      [id, uid]
    );
    if (!leadR.rows.length) return res.status(404).json({ error: 'Lead not found' });
    const lead = leadR.rows[0];

    // Journal entries
    const actR = await pool.query(
      `SELECT body, created_at FROM lead_activities
        WHERE lead_id=$1 AND user_id=$2 AND type='note_added'
        ORDER BY created_at DESC LIMIT 20`,
      [id, uid]
    );
    const journalText = actR.rows.map((r) =>
      `[${new Date(r.created_at).toLocaleDateString()}] ${r.body}`
    ).join('\n');

    const hasContent = journalText.trim() || (lead.notes || '').trim();
    if (!hasContent) return res.status(400).json({ error: 'No notes to summarize' });

    const prompt = `You are summarizing CRM notes for a vehicle wrap salesperson preparing for a client call or handoff.

Company: ${lead.company} (${lead.category}, status: ${lead.status})

Pinned Notes:
${lead.notes || '(none)'}

Journal Entries (newest first):
${journalText || '(none)'}

Write a concise executive brief (3–5 sentences max) covering:
- Key facts about this prospect and their wrap opportunity
- Current status and next recommended action
- Any objections, concerns, or special considerations
- Important context for whoever calls next

Write in third person, present tense. No bullet points — flowing prose only.`;

    const resp = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 200,
        messages: [{ role: 'user', content: prompt }],
      }),
    });

    if (!resp.ok) throw new Error(`Anthropic ${resp.status}`);
    const ai = await resp.json();
    const summary = ai.content?.[0]?.text?.trim() ?? '';

    res.json({ ok: true, summary });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// ── AI Lead Category Suggestion ───────────────────────────────────────────────
// Fast single-call inference: given a company name, suggest the best wrap
// category, estimated fleet size range, and a one-line pitch angle.
app.post('/ai/suggest-lead', authMiddleware, async (req, res) => {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return res.status(503).json({ error: 'AI not configured' });

  const { company } = req.body || {};
  if (!company || typeof company !== 'string' || company.trim().length < 2) {
    return res.status(400).json({ error: 'company required' });
  }

  try {
    const prompt = `You are classifying a business for a vehicle wrap sales CRM.

Company name: "${company.trim()}"

Based only on the company name, infer:
1. The most likely wrap category from this list:
   fleet, construction, gc_referral, dinoc, reatec, colorchange, wallgraphics, racing, design
2. Estimated fleet size range (e.g. "5-15", "20-50", "unknown")
3. A one-line wrap pitch angle (10-15 words max, specific to their business type)
4. Your confidence: high | medium | low

Respond with ONLY valid JSON, no extra text:
{"category":"fleet","fleetRange":"10-30","pitchAngle":"...","confidence":"medium"}`;

    const resp = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 120,
        messages: [{ role: 'user', content: prompt }],
      }),
    });

    if (!resp.ok) throw new Error(`Anthropic ${resp.status}`);
    const ai = await resp.json();
    const raw = ai.content?.[0]?.text ?? '{}';
    let suggestion;
    try { suggestion = JSON.parse(raw); } catch { suggestion = {}; }

    res.json({ ok: true, suggestion });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// ── AI Competitor Counter-Strategy ────────────────────────────────────────────
// Generates a battle card for beating a named competitor.
app.post('/ai/counter-strategy', authMiddleware, requireShopFlow, async (req, res) => {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return res.status(503).json({ error: 'AI not configured' });

  const uid = String(req.user.id);
  const { competitor } = req.body || {};
  if (!competitor) return res.status(400).json({ error: 'competitor required' });

  try {
    // Pull recent losses to this competitor for context
    const lossR = await pool.query(
      `SELECT l.company, l.category, a.notes
         FROM lead_activities a
         JOIN leads l ON l.id = a.lead_id AND l.user_id = $1
        WHERE a.user_id = $1
          AND a.metadata->>'competitor' ILIKE $2
        ORDER BY a.created_at DESC LIMIT 10`,
      [uid, `%${competitor}%`]
    );

    const losses = lossR.rows.map((r) => `- ${r.company} (${r.category}): ${r.notes || 'no notes'}`).join('\n') || 'No detailed loss data available yet.';

    const prompt = `You are a vehicle wrap sales strategist. A wrap shop lost some deals to a competitor named "${competitor}".

Recent losses to this competitor:
${losses}

Generate a concise competitive battle card in valid JSON with these exact keys:
{
  "theirStrengths": ["2-3 bullet strings about why clients might choose them"],
  "ourAdvantages": ["2-3 bullet strings about genuine wrap shop advantages to emphasize"],
  "talkTrack": ["3-4 specific sentences or questions to say on a sales call to reframe the comparison"],
  "closingMove": "One powerful closing statement or offer to use when the prospect mentions this competitor"
}
Return ONLY the JSON, no other text.`;

    const resp = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-opus-4-5',
        max_tokens: 600,
        messages: [{ role: 'user', content: prompt }],
      }),
    });

    if (!resp.ok) throw new Error(`Anthropic ${resp.status}`);
    const ai = await resp.json();
    const raw = ai.content?.[0]?.text ?? '{}';
    let card;
    try { card = JSON.parse(raw); } catch { card = {}; }

    res.json({ ok: true, competitor, card, lossCount: lossR.rowCount });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

