    if (title !== undefined) { sets.push(`title=$${idx++}`); vals.push(title); }
    if (notes !== undefined) { sets.push(`notes=$${idx++}`); vals.push(notes); }
    if (due_date !== undefined) { sets.push(`due_date=$${idx++}`); vals.push(due_date || null); }
